def btn(place, label='🧩 להוסיף לכרום – בחינם'):
    return '<a class="btn btn-gold" href="%s%s" target="_blank" rel="noopener" data-store="%s">%s</a>' % (S, place, place, label)

def page(slug, title, desc, og, crumb, h1, sub, builtin, tosaf, fig, faq, seo, crumbs=None):
    place = slug.replace('/', '_').replace('-', '_')
    crumbs = crumbs or [["מחשב וטלפון", "/kelim/machshev/"], [crumb, None]]
    meta = {"site": "kelim", "nav": "tchumim", "tool": "machshev_" + place, "title": title + " | הכלים של גילעד רחמים", "description": desc, "og_title": og,
            "priority": "0.8", "crumbs": crumbs,
            "head": '<link rel="stylesheet" href="/assets/seo-txt.css">' + STYLE + '<script type="application/ld+json">' + json.dumps({"@context": "https://schema.org", "@type": "FAQPage", "mainEntity": [{"@type": "Question", "name": q, "acceptedAnswer": {"@type": "Answer", "text": a}} for q, a in faq]}, ensure_ascii=False) + '</script>'}
    o = '<!--meta ' + json.dumps(meta, ensure_ascii=False, indent=2) + ' -->\n'
    o += '<header class="k-hero">\n  <h1>%s</h1>\n  <p class="sub">%s</p>\n  <div class="actions">\n    %s\n    <a class="btn btn-line" href="#how-h">איך עושים את זה</a>\n  </div>\n  <p class="muted" style="font-size:.92rem;margin:.6rem 0 0">❤ מיזם חסד של מיזם הכלים: בחינם, בלי פרסומות ובלי לאסוף מידע. מהחנות הרשמית של כרום.</p>\n</header>\n' % (h1, sub, btn(place + '_hero'))
    o += '<section class="k-sec" aria-labelledby="how-h">\n  <h2 id="how-h">איך עושים את זה</h2>\n  <div class="ts-two">\n    <div><h3>בלי שום תוסף</h3>\n%s\n    </div>\n    <div><h3>בלחיצה, עם התוסף</h3>\n%s\n      <p>%s</p>\n    </div>\n  </div>\n' % (builtin, tosaf, btn(place + '_steps', '🧩 להוסיף לכרום'))
    if fig:
        o += '  <figure class="ts-fig"><img src="/assets/%s" width="960" height="600" loading="lazy" alt="%s"><figcaption>%s</figcaption></figure>\n' % fig
    o += '</section>\n'
    rel = ' · '.join('<a class="gold" href="/kelim/machshev/%s/">%s</a>' % (s, n) for s, n in ALL if s != slug)
    o += '\n<!--seo-txt-->\n<section class="k-sec seo-txt" aria-labelledby="seo-h">\n' + seo + '\n  <h3>עוד דברים שהתוסף עושה</h3>\n  <p>' + rel + ' · <a class="gold" href="/kelim/tochen/tirgum/atar/">תרגום אתר לעברית</a> · <a class="gold" href="/kelim/machshev/chatima/tosaf/">כל מה שיש בתוסף</a>.</p>\n</section>\n'
    o += '<section class="k-sec seo-faq" aria-labelledby="seo-faq-h">\n  <h2 id="seo-faq-h">שאלות ותשובות</h2>\n' + '\n'.join('  <details><summary>%s</summary><p>%s</p></details>' % qa for qa in faq) + '\n</section>\n<!--/seo-txt-->\n'
    p = R / 'src/pages/kelim/machshev' / slug / 'index.html'
    p.parent.mkdir(parents=True, exist_ok=True)
    io.open(p, 'w', encoding='utf-8', newline='\n').write(o)
    print('wrote', slug)

def ul(*items): return '      <ul>\n' + '\n'.join('        <li>%s</li>' % i for i in items) + '\n      </ul>'
def ol(*items): return '      <ol>\n' + '\n'.join('        <li>%s</li>' % i for i in items) + '\n      </ol>'
POP = 'לוחצים על כפתור התוסף 🧩 (ליד שורת הכתובת)'

